-- Create scan-originals storage bucket for AI extraction source images
--
-- This bucket stores original uploaded images before AI extraction.
-- Images are uploaded here, then referenced by scan_sessions for extraction.
--
-- Path conventions:
--   Vendor scans: {eventId}/capture-{timestamp}-{uuid}.{ext}
--   Style scans:  {eventId}/{vendorId}/capture-{timestamp}-{uuid}.{ext}
--
-- Note: Paths are generated by src/lib/upload/imageUpload.ts
-- - Unique filename uses timestamp + UUID
-- - Vendor ID is included for style scans only
-- - File extension matches the detected MIME type
--
-- Security: Private bucket - images are served via signed URLs only
-- Access: Authenticated users can upload, service role can read/write

-- Insert the bucket (idempotent)
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'scan-originals',
  'scan-originals',
  false, -- Private bucket
  10485760, -- 10MB max file size
  ARRAY['image/jpeg', 'image/png', 'image/webp', 'image/gif']
)
on conflict (id) do update set
  name = excluded.name,
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

-- RLS Policies for scan-originals bucket

-- Authenticated users can upload images (needed for capture workflow)
create policy "Authenticated users can upload to scan-originals"
on storage.objects
for insert
to authenticated
with check (
  bucket_id = 'scan-originals'
  -- Additional folder-based restrictions could be added here
  -- e.g., path starts with their event_id
);

-- Authenticated users can read their own uploads (needed for preview)
create policy "Authenticated users can read own scan originals"
on storage.objects
for select
to authenticated
using (
  bucket_id = 'scan-originals'
  -- Users can read images they uploaded
  -- Additional ownership checks could be added via path patterns
);

-- Service role has full access (needed for edge functions)
create policy "Service role can manage scan-originals"
on storage.objects
for all
to service_role
using (bucket_id = 'scan-originals')
with check (bucket_id = 'scan-originals');

-- Allow authenticated users to delete their own uploads (needed for retry/cleanup)
create policy "Authenticated users can delete own scan originals"
on storage.objects
for delete
to authenticated
using (
  bucket_id = 'scan-originals'
);
